const row={project_id:state.activeProject.id,character_id:s.character_id||null,character_ids:s.character_ids||[],scene_order:i+1,duration_seconds:s.duration,visual_prompt:s.visual_prompt,dialogue_text:JSON.stringify({__dialogueLines:dialogueData,__sceneVariants:{image_variants:imageVariantData,selected_image_variant:s.selected_image_variant||0,video_variants:s.video_variants||[],selected_video_variant:s.selected_video_variant||0}}),voice_language:s.voice_language,sound_prompt:s.sound_prompt,reference_image_path:refPath,generated_video_url:s.generated_video_url||null,video_provider:s.video_provider||null,video_task_id:s.video_task_id||null,video_task_status:s.video_task_status||null,selected_dialogue_id:s.selected_dialogue_id||null,music_mood:s.music_mood||"magical",background_music_path:musicPath,sfx_audio_path:sfxPath};
