async function pollSceneVideo(scene,index,button){
  const provider="magic-hour",taskId=scene.video_task_id;
  const maxAttempts=48;
  const pollInterval=5000;
  for(let attempt=0;attempt<maxAttempts;attempt++){
    await new Promise(resolve=>setTimeout(resolve,pollInterval));
    const result=await aiRequest("/api/video/status",{provider,taskId});
    scene.video_task_status=result.status||"processing";
    if(result.videoUrl){scene.video_variants=Array.isArray(scene.video_variants)?scene.video_variants:[];if(scene.generated_video_url&&!scene.video_variants.some(v=>v.url===scene.generated_video_url))scene.video_variants.unshift({url:scene.generated_video_url,createdAt:"existing"});const found=scene.video_variants.findIndex(v=>v.url===result.videoUrl);if(found<0)scene.video_variants.push({url:result.videoUrl,taskId,createdAt:new Date().toISOString()});scene.selected_video_variant=scene.video_variants.findIndex(v=>v.url===result.videoUrl);scene.generated_video_url=result.videoUrl;scene.video_task_status="completed";scene.video_task_id=taskId;saveLocal();renderSceneList();renderTimeline();toast(`Scene ${index+1} video option ${scene.selected_video_variant+1} is ready.`);return;}
    if(["failed","error","cancelled","canceled"].includes(String(result.status).toLowerCase()))throw new Error(result.error||"Video generation failed.");
    if(button)button.textContent=`Processing… ${attempt+1}/${maxAttempts}`;
    try{saveLocal();}catch{}
  }
  throw new Error("This video is still processing. Use Check status later; the task is still saved.");
}
async function generateSceneVideo(index,button){
  const scene=state.activeProject?.scenes?.[index];if(!scene)return;
  const card=button.closest(".scene-card");
  const image=scene.generated_image;
  if(!image){toast("Generate or upload a scene image first.");return;}
  const provider="magic-hour";
  const prompt=card.querySelector(`[data-video-prompt="${index}"]`).value.trim();
  if(!prompt){toast("Add a motion direction first.");return;}
  scene.video_provider="magic-hour";scene.video_prompt=prompt;scene.video_task_status="submitting";button.disabled=true;button.textContent="Submitting…";
  try{
    const created=await aiRequest("/api/video/generate",{provider,image,prompt,duration:Math.max(5,Math.min(15,Number(scene.duration)||5)),ratio:state.activeProject.ratio||"16:9"});
    scene.video_task_id=created.taskId;scene.video_task_status=created.status||"submitted";saveLocal();renderSceneList();
    const refreshed=document.querySelector(`[data-scene="${index}"] [data-check-scene-video]`);
    await pollSceneVideo(scene,index,refreshed);
  }catch(err){scene.video_task_status="failed";try{saveLocal();}catch{}toast(err.message);renderSceneList();}
  finally{const current=document.querySelector(`[data-scene="${index}"] [data-generate-scene-video]`);if(current){current.disabled=!scene.generated_image;current.textContent="▶ Generate another video take";}}
}
